function splitAt(value, punctuation) {
  const raw = [];
  let current = "";
  let depth = 0;
  for (const char of value) {
    current += char;
    if (/[（【《「『“‘]/u.test(char)) depth += 1;
    if (/[）】》」』”’]/u.test(char)) depth = Math.max(0, depth - 1);
    if (depth === 0 && punctuation.test(char)) {
      raw.push(current);
      current = "";
    }
  }
  if (current) raw.push(current);
  return raw;
}

function phraseSegments(sentence, literal) {
  if (!literal && renderedCopy.has(sentence)) return renderedCopy.get(sentence);
  if (!literal && sentenceCopy.has(sentence)) return sentenceCopy.get(sentence);
  if (!literal && readingCopy.has(sentence)) return readingCopy.get(sentence);
  const raw = splitAt(sentence, /[，。！？；：\n]/u);
  const parts = [];
  for (const part of raw) {
    const previous = parts.at(-1);
    if (previous && (closingPunctuation.test(part) || dependentStart.test(part.trimStart()) || dependentEnd.test(previous.trimEnd()))) {
      parts[parts.length - 1] += part;
    } else {
      parts.push(part);
    }
  }
  return parts.flatMap((part) => literal ? [part] : readingCopy.get(part) || [part]);
}

export function semanticSegments(value, { literal = false } = {}) {
  const source = String(value ?? "");
  if (!source) return [];
  return splitAt(source, /[。！？\n]/u).flatMap((sentence) => phraseSegments(sentence, literal));
}

export function normalizeSearch(value) {
  return String(value ?? "").normalize("NFKC").toLocaleLowerCase("zh-Hans").trim().replace(/\s+/gu, " ");
}

export function searchPublicArticles(items, query) {
  const terms = normalizeSearch(query).split(" ").filter(Boolean);
  if (!terms.length) return [...items];
  return items.filter((article) => {
    const text = normalizeSearch(JSON.stringify({
      title: article.title,
      summary: article.summary,
      tags: article.tags,
      status: article.status,
      sections: article.sections,
    }));
    return terms.every((term) => text.includes(term));
  });
}

export function formatArticleDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/u.test(String(value)) ? String(value) : "";
}
